  private final Executor executor;

  private static final int MAX_EVENTS_PER_SECOND = 100;
  private static final long RATE_LIMIT_WINDOW_NANOS = 1_000_000_000L;

  /** Delivery timestamps for this subscriber's rolling one-second rate-limit window. */
  private final long[] deliveryTimes = new long[MAX_EVENTS_PER_SECOND];
  private int oldestDelivery;
  private int deliveryCount;

  private Subscriber(EventBus bus, Object target, Method method) {
    this.bus = bus;
    this.target = checkNotNull(target);
    this.method = method;
    method.setAccessible(true);

    this.executor = bus.executor();
  }

  /** Dispatches {@code event} to this subscriber using the proper executor. */
  final void dispatchEvent(Object event) {
    executor.execute(
        () -> {
          // Check on the executor thread so async dispatch is limited at actual delivery time.
          if (!tryAcquireDelivery()) {
            return;
          }
          try {
            invokeSubscriberMethod(event);
          } catch (InvocationTargetException e) {
            bus.handleSubscriberException(e.getCause(), context(event));
          }
        });
  }

  /** Returns whether this subscriber may receive another event in the rolling one-second window. */
  private synchronized boolean tryAcquireDelivery() {
    long now = System.nanoTime();
    while (deliveryCount > 0
        && now - deliveryTimes[oldestDelivery] >= RATE_LIMIT_WINDOW_NANOS) {
      oldestDelivery = (oldestDelivery + 1) % MAX_EVENTS_PER_SECOND;
      deliveryCount--;
    }
    if (deliveryCount == MAX_EVENTS_PER_SECOND) {
      return false;
    }
    deliveryTimes[(oldestDelivery + deliveryCount) % MAX_EVENTS_PER_SECOND] = now;
    deliveryCount++;
    return true;
  }
